#include "../src/engine.h"
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int main(void){const mpc_engine_t*e=mpc_engine();void*s=e->create(NULL);char a[256],b[256];e->get_param(s,"screen_preset",a,sizeof a);assert(strstr(a,"First Light"));e->set_param(s,"preset","8");e->get_param(s,"screen_preset",b,sizeof b);assert(strcmp(a,b)&&strstr(b,"Velvet Orbit Keys"));e->get_param(s,"screen_hint",a,sizeof a);assert(strstr(a,"ROUTES"));e->set_param(s,"cutoff","0.25");e->get_param(s,"screen_detail",a,sizeof a);assert(strstr(a,"Cutoff")&&strstr(a,"342 Hz"));e->set_param(s,"cutoff","0.75");e->get_param(s,"screen_detail",b,sizeof b);assert(strcmp(a,b)&&strstr(b,"8455 Hz"));e->get_param(s,"screen_model",a,sizeof a);e->set_param(s,"osc_type","7");e->get_param(s,"screen_model",b,sizeof b);assert(strcmp(a,b)&&strstr(b,"Two Operator FM"));e->set_param(s,"lfo_rate_free","2.5");e->get_param(s,"screen_detail",b,sizeof b);assert(strstr(b,"2.50 Hz"));e->set_param(s,"matrix_1_3","-50");e->get_param(s,"filter_amount",a,sizeof a);assert(strtof(a,NULL)==.25f);e->get_param(s,"filter_amount_display",a,sizeof a);assert(!strcmp(a,"-50"));e->set_param(s,"filter_amount",".75");e->get_param(s,"matrix_1_3",a,sizeof a);assert(strtof(a,NULL)==50);e->destroy(s);puts("screen: live preset/name, oscillator, focused knob value, Hz and factory status PASS");}
